/* V1.6.2 · informe infográfico + termómetro general y por territorio */
(()=>{
'use strict';
const VERSION='1.6.2';
const api=window.CongElCalafateTerritoriosV150,OFF=window.CongTerritoryOfficialData||{};if(!api||!OFF.data)return;
const DATA=OFF.data,STATE_KEY='cec_territory_official_v150';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const sideKey=(i,s)=>i+'::'+s;let filter='all';
function state(){try{return JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{};}catch(_){return{};}}
function metric(n){n=String(n);const d=DATA[n],done=state()[n]?.done||{},keys=[];if(!d)return{done:0,total:0,pct:0};if(d.type==='tramos')d.items.forEach(x=>keys.push(sideKey(x,'territorio')));else d.items.forEach(x=>['N','E','S','O'].forEach(s=>keys.push(sideKey(x,s))));const c=keys.filter(k=>done[k]).length;return{done:c,total:keys.length,pct:keys.length?Math.round(c*100/keys.length):0};}
function aggregate(){let done=0,total=0,completed=0,active=0,empty=0;const rows=[];for(let n=1;n<=102;n++){const m=metric(n);done+=m.done;total+=m.total;if(m.pct===100&&m.total)completed++;else if(m.done)active++;else empty++;rows.push({n,...m});}return{done,total,pct:total?Math.round(done*100/total):0,completed,active,empty,rows};}
function inject(){if($('#cecV162ReportStyle'))return;const s=document.createElement('style');s.id='cecV162ReportStyle';s.textContent=`
.cec-v162-report-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.cec-v162-report-btn{border:0;border-radius:13px;background:#0b5fa5;color:#fff;font-weight:900;padding:10px 13px}.cec-v162-mini{display:flex;align-items:center;gap:10px;margin-top:10px;padding:10px 12px;border:1px solid #dce7eb;border-radius:15px;background:#fbfdfe}.cec-v162-mini-t{width:14px;height:44px;border:2px solid #52707d;border-radius:9px;position:relative;background:#edf3f5;flex:0 0 auto}.cec-v162-mini-t:after{content:'';position:absolute;width:20px;height:20px;border-radius:50%;background:#52707d;left:50%;bottom:-8px;transform:translateX(-50%)}.cec-v162-mini-t i{position:absolute;z-index:1;left:2px;right:2px;bottom:2px;background:#16835d;border-radius:6px}.cec-v162-mini strong{display:block;color:#173e52;font-size:13px}.cec-v162-mini small{display:block;color:#728994;font-size:11px;margin-top:2px}
#cecV162Report{position:fixed;inset:0;z-index:9300;background:#f3f7f9;color:#183746;display:none;overflow:auto}#cecV162Report.open{display:block}.cec-v162-rhead{position:sticky;top:0;z-index:3;display:flex;align-items:center;gap:10px;background:#103f57;color:#fff;padding:10px 12px}.cec-v162-rback{width:44px;height:44px;border:0;border-radius:13px;background:rgba(255,255,255,.13);color:#fff;font-size:28px}.cec-v162-rhead div{flex:1}.cec-v162-rhead small{display:block;font-size:9px;opacity:.7;font-weight:900;letter-spacing:.08em}.cec-v162-rhead strong{display:block;font-size:18px}.cec-v162-rwrap{max-width:850px;margin:auto;padding:14px}.cec-v162-hero{display:grid;grid-template-columns:82px 1fr;align-items:center;gap:14px;padding:18px;border-radius:24px;background:linear-gradient(135deg,#0b4f6c,#16789e);color:#fff}.cec-v162-thermo{width:38px;height:126px;border:4px solid #fff;border-radius:25px;position:relative;margin:auto;background:rgba(255,255,255,.14)}.cec-v162-thermo:after{content:'';position:absolute;width:54px;height:54px;border-radius:50%;background:#fff;left:50%;bottom:-24px;transform:translateX(-50%);box-shadow:inset 0 0 0 9px #16835d}.cec-v162-thermo i{position:absolute;left:7px;right:7px;bottom:8px;background:#16835d;border-radius:15px}.cec-v162-hero .pct{font-size:48px;font-weight:950;line-height:1}.cec-v162-hero p{margin:6px 0 0;font-size:11px;opacity:.82}.cec-v162-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.cec-v162-stat{background:#fff;border:1px solid #dbe6eb;border-radius:16px;padding:11px}.cec-v162-stat strong{display:block;font-size:21px;color:#153e52}.cec-v162-stat span{display:block;font-size:9px;color:#738994;font-weight:900}.cec-v162-section{background:#fff;border:1px solid #dbe6eb;border-radius:20px;padding:13px;margin-top:12px}.cec-v162-section h3{margin:0 0 9px;font-size:15px;color:#173e52}.cec-v162-heat{display:grid;grid-template-columns:repeat(12,1fr);gap:5px}.cec-v162-heat button{aspect-ratio:1;border:0;border-radius:7px;font-size:9px;font-weight:900;background:#edf2f4;color:#617984}.cec-v162-heat button.p1{background:#fff1d5;color:#8c5c08}.cec-v162-heat button.p2{background:#dff1f6;color:#0b6687}.cec-v162-heat button.p3{background:#e1f5eb;color:#19724f}.cec-v162-heat button.done{background:#16835d;color:#fff}.cec-v162-search{width:100%;box-sizing:border-box;border:1px solid #d7e3e8;border-radius:13px;padding:10px 12px;margin-bottom:9px}.cec-v162-filters{display:flex;gap:6px;overflow:auto;margin-bottom:9px}.cec-v162-filter{border:1px solid #d7e3e8;background:#fff;border-radius:999px;padding:7px 10px;font-size:10px;font-weight:900;white-space:nowrap}.cec-v162-filter.active{background:#103f57;color:#fff}.cec-v162-list{display:grid;gap:7px}.cec-v162-row{display:grid;grid-template-columns:45px 1fr auto;gap:9px;align-items:center;border:1px solid #e0e9ed;border-radius:14px;padding:9px;background:#fbfdfe;text-align:left}.cec-v162-num{height:42px;border-radius:12px;background:#edf3f5;display:grid;place-items:center;font-weight:950}.cec-v162-row strong{display:block;font-size:11px;color:#173e52}.cec-v162-row small{font-size:9px;color:#7a8e97}.cec-v162-rbar{display:block;height:6px;background:#e8eff2;border-radius:99px;overflow:hidden;margin-top:5px}.cec-v162-rbar i{display:block;height:100%;background:#16835d}.cec-v162-rpct{font-weight:950;color:#1a654e}@media(max-width:520px){.cec-v162-heat{grid-template-columns:repeat(9,1fr)}}`;
document.head.appendChild(s);}
function install(){inject();const top=$('.cec-t15-top');if(top&&!$('#cecV162ReportActions')){const d=document.createElement('div');d.id='cecV162ReportActions';d.className='cec-v162-report-actions';d.innerHTML='<button id="cecV162OpenReport" class="cec-v162-report-btn" type="button">Informe + termómetro</button>';top.appendChild(d);const m=document.createElement('div');m.id='cecV162Mini';m.className='cec-v162-mini';m.innerHTML='<span class="cec-v162-mini-t"><i></i></span><div><strong>Termómetro del territorio</strong><small>0% realizado</small></div>';top.appendChild(m);$('#cecV162OpenReport').onclick=openReport;}if(!$('#cecV162Report')){const r=document.createElement('section');r.id='cecV162Report';r.innerHTML='<header class="cec-v162-rhead"><button class="cec-v162-rback" type="button">‹</button><div><small>INFORME INFOGRÁFICO</small><strong>Avance de territorios</strong></div></header><main id="cecV162ReportBody" class="cec-v162-rwrap"></main>';document.body.appendChild(r);$('.cec-v162-rback',r).onclick=closeReport;}updateMini();}
function updateMini(){const n=String($('#t15Select')?.value||'1'),m=metric(n),root=$('#cecV162Mini');if(!root)return;root.querySelector('i').style.height=Math.max(0,m.pct)+'%';root.querySelector('small').textContent=`Territorio ${n} · ${m.done}/${m.total} · ${m.pct}% realizado`;}
function openReport(){$('#cecV162Report').classList.add('open');render();}
function closeReport(){$('#cecV162Report')?.classList.remove('open');}
function render(){const a=aggregate(),root=$('#cecV162ReportBody');if(!root)return;root.innerHTML=`<section class="cec-v162-hero"><div class="cec-v162-thermo"><i style="height:${Math.max(0,a.pct)}%"></i></div><div><div style="font-size:10px;font-weight:900;opacity:.75">AVANCE GENERAL</div><div class="pct">${a.pct}%</div><p>${a.done} de ${a.total} lados/tramos realizados.</p></div></section><div class="cec-v162-stats"><div class="cec-v162-stat"><strong>${a.completed}</strong><span>COMPLETADOS</span></div><div class="cec-v162-stat"><strong>${a.active}</strong><span>EN CURSO</span></div><div class="cec-v162-stat"><strong>${a.empty}</strong><span>SIN INICIAR</span></div></div><section class="cec-v162-section"><h3>Mapa de avance · 1 a 102</h3><div class="cec-v162-heat">${a.rows.map(x=>`<button data-t="${x.n}" class="${x.pct===100?'done':x.pct>=67?'p3':x.pct>=34?'p2':x.done?'p1':''}">${x.n}</button>`).join('')}</div></section><section class="cec-v162-section"><h3>Termómetro por territorio</h3><input id="cecV162RSearch" class="cec-v162-search" inputmode="numeric" placeholder="Buscar territorio…"><div class="cec-v162-filters"><button class="cec-v162-filter active" data-f="all">Todos</button><button class="cec-v162-filter" data-f="pending">Pendientes</button><button class="cec-v162-filter" data-f="active">En curso</button><button class="cec-v162-filter" data-f="done">Completados</button></div><div id="cecV162RList" class="cec-v162-list"></div></section>`;$$('[data-t]',root).forEach(b=>b.onclick=()=>go(b.dataset.t));$$('[data-f]',root).forEach(b=>b.onclick=()=>{filter=b.dataset.f;$$('[data-f]',root).forEach(x=>x.classList.toggle('active',x===b));renderList();});$('#cecV162RSearch').oninput=renderList;renderList();}
function renderList(){const root=$('#cecV162RList');if(!root)return;const q=String($('#cecV162RSearch')?.value||''),rows=aggregate().rows.filter(x=>{if(q&&!String(x.n).includes(q))return false;if(filter==='done')return x.pct===100;if(filter==='active')return x.done&&x.pct<100;if(filter==='pending')return x.pct<100;return true;});root.innerHTML=rows.map(x=>`<button class="cec-v162-row" data-open="${x.n}"><span class="cec-v162-num">${x.n}</span><span><strong>${x.pct===100?'Completado':x.done?'En curso':'Sin iniciar'}</strong><small>${x.done} de ${x.total} lados/tramos</small><span class="cec-v162-rbar"><i style="width:${x.pct}%"></i></span></span><span class="cec-v162-rpct">${x.pct}%</span></button>`).join('');$$('[data-open]',root).forEach(b=>b.onclick=()=>go(b.dataset.open));}
function go(n){closeReport();api.select(String(n),false);setTimeout(()=>$('.cec-map-card')?.scrollIntoView({behavior:'smooth',block:'start'}),80);}
const obs=new MutationObserver(()=>{updateMini();if($('#cecV162Report')?.classList.contains('open'))render();});setTimeout(()=>{['t15Pct','t15Select','t15Title'].forEach(id=>{const e=document.getElementById(id);if(e)obs.observe(e,{subtree:true,childList:true,attributes:true,characterData:true});});},100);
install();setTimeout(install,500);window.CongElCalafateTerritoriosReportV162={version:VERSION,metric,aggregate,open:openReport,refresh:updateMini};
})();
